$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$Stage='D:\Claude\swiftright\.factory-work\hosts\image';$Requests=Join-Path $Stage 'requests-final-r1'
if(@(Get-Process swift,swiftc,swift-build,clang,FactoryProbe -ErrorAction SilentlyContinue).Count){throw 'compiler/native lane busy'}
if(Test-Path -LiteralPath $Requests){throw 'fresh final requests required'}
New-Item -ItemType Directory -Path $Requests|Out-Null
$Rows='[{"path":"plan-prebuild-native-r2.json","bytes":9868,"sha256":"bb8469b0cc156b89db0b1684e37ba83d3446af604a7984d38cb7ae1bfe9ac616","base64":""},{"path":"build-owned-native-r2.ps1","bytes":11165,"sha256":"3c5b4096e55e2c74942c5f25b95d2c8a514af735932afa31a9411425e509fe0a","base64":""},{"path":"plan-final-v4.json","bytes":36889,"sha256":"0102becf57242fc2084a39bf5aa63d6956fb0ac0393492fc2cf0d8a8b19ee171","base64":""},{"path":"build-owned-final-v1.ps1","bytes":11152,"sha256":"c5a60250ce3b9005e49a642125fdeb882589850e04a2fecfd98de2d44d9c93d2","base64":""},{"path":"final-remote-entry.ps1","bytes":3089,"sha256":"2d9c2466820baf7816974ff7d6883fcf9cc9cf87a9845d18212b6c16de4af9ab","base64":""}]'|ConvertFrom-Json
foreach($Row in @($Rows)){
  $P=Join-Path $Requests $Row.path
  [IO.File]::WriteAllBytes($P,[Convert]::FromBase64String($Row.base64))
